SELECT json_build_object('database',current_database(),'migrations',(SELECT count(*) FROM schema_migrations),'checksums',(SELECT count(*) FROM schema_migration_checksums),'byte_versions',(SELECT count(*) FROM pet_schema.document_byte_versions),'events',(SELECT count(*) FROM pet_schema.document_byte_events),'job_sources',(SELECT count(*) FROM pet_schema.ocr_job_byte_sources),'receipts',(SELECT count(*) FROM pet_schema.ocr_attempt_byte_receipts),'result_bindings',(SELECT count(*) FROM pet_schema.ocr_result_byte_bindings),'deadlocks',(SELECT deadlocks FROM pg_stat_database WHERE datname=current_database()),'other_idle_in_transaction',(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND state='idle in transaction'),'provenance_triggers',(SELECT json_agg(json_build_object('table',c.relname,'trigger',t.tgname,'enabled',t.tgenabled) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname IN('document_byte_versions','document_byte_events','ocr_job_byte_sources','ocr_attempt_byte_receipts','ocr_result_byte_bindings') AND NOT t.tgisinternal));
